export const PHYSICS_FLASHCARDS: Class11Flashcard[] = [
  // ===== UNITS AND MEASUREMENTS (p2) — 60 cards =====
  { id: "phy11-p2-pq-001", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Physical Quantities", type: "definition", front: "What are physical quantities?", back: "Quantities that can be measured directly or indirectly and in terms of which the laws of physics are expressed.", difficulty: "easy", examImportance: "high", tags: ["physical quantities", "basics"] },
  { id: "phy11-p2-pq-002", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Physical Quantities", type: "difference", front: "Difference between fundamental and derived quantities?", back: "Fundamental quantities are independent (mass, length, time, etc.). Derived quantities are defined in terms of fundamental quantities (speed = length/time).", difficulty: "easy", examImportance: "high", tags: ["fundamental", "derived", "basics"] },
  { id: "phy11-p2-pq-003", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Physical Quantities", type: "concept", front: "How many fundamental quantities are there in SI?", back: "Seven: mass, length, time, electric current, temperature, luminous intensity, and amount of substance.", difficulty: "easy", examImportance: "high", tags: ["SI", "fundamental", "seven"] },
  { id: "phy11-p2-pq-004", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Physical Quantities", type: "unit", front: "What is the SI unit of luminous intensity?", back: "Candela (cd)", difficulty: "medium", examImportance: "medium", tags: ["SI units", "candela", "luminous intensity"] },
  { id: "phy11-p2-pq-005", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Physical Quantities", type: "unit", front: "What is the SI unit of amount of substance?", back: "Mole (mol)", difficulty: "easy", examImportance: "high", tags: ["SI units", "mole"] },
  { id: "phy11-p2-si-006", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "SI Units", type: "definition", front: "What is the SI system of units?", back: "Systeme Internationale d'Unites — a internationally accepted coherent system of units based on seven fundamental quantities.", difficulty: "easy", examImportance: "medium", tags: ["SI", "units", "system"] },
  { id: "phy11-p2-si-007", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "SI Units", type: "unit", front: "SI unit of electric current?", back: "Ampere (A)", difficulty: "easy", examImportance: "high", tags: ["SI", "ampere", "current"] },
  { id: "phy11-p2-si-008", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "SI Units", type: "unit", front: "SI unit of thermodynamic temperature?", back: "Kelvin (K)", difficulty: "easy", examImportance: "high", tags: ["SI", "kelvin", "temperature"] },
  { id: "phy11-p2-dim-009", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Dimensional Analysis", type: "definition", front: "What are dimensions?", back: "Powers to which fundamental quantities must be raised to represent a physical quantity.", difficulty: "easy", examImportance: "high", tags: ["dimensions", "basics"] },
  { id: "phy11-p2-dim-010", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Dimensional Analysis", type: "formula", front: "What is the dimensional formula of force?", back: "[MLT⁻²]", explanation: "F = ma → [M][LT⁻²] = [MLT⁻²]", difficulty: "easy", examImportance: "high", tags: ["dimensional formula", "force"] },
  { id: "phy11-p2-dim-011", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Dimensional Analysis", type: "formula", front: "Dimensional formula of energy?", back: "[ML²T⁻²]", explanation: "E = ½mv² → [M][L²T⁻²]", difficulty: "medium", examImportance: "high", tags: ["dimensional formula", "energy"] },
  { id: "phy11-p2-dim-012", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Dimensional Analysis", type: "formula", front: "Dimensional formula of power?", back: "[ML²T⁻³]", explanation: "P = E/t → [ML²T⁻²]/[T] = [ML²T⁻³]", difficulty: "medium", examImportance: "high", tags: ["dimensional formula", "power"] },
  { id: "phy11-p2-dim-013", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Dimensional Analysis", type: "formula", front: "Dimensional formula of pressure?", back: "[ML⁻¹T⁻²]", explanation: "P = F/A → [MLT⁻²]/[L²] = [ML⁻¹T⁻²]", difficulty: "medium", examImportance: "high", tags: ["dimensional formula", "pressure"] },
  { id: "phy11-p2-dim-014", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Dimensional Analysis", type: "formula", front: "Dimensional formula of gravitational constant G?", back: "[M⁻¹L³T⁻²]", explanation: "From F = Gm₁m₂/r² → G = Fr²/(m₁m₂) → [MLT⁻²][L²]/[M²] = [M⁻¹L³T⁻²]", difficulty: "hard", examImportance: "high", tags: ["dimensional formula", "G", "gravitation"] },
  { id: "phy11-p2-dim-015", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Dimensional Analysis", type: "law", front: "State the principle of homogeneity of dimensions.", back: "For an equation to be dimensionally correct, all terms on both sides must have the same dimensions.", difficulty: "easy", examImportance: "high", tags: ["principle", "homogeneity", "dimensions"] },
  { id: "phy11-p2-dim-016", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Dimensional Analysis", type: "application", front: "What are the uses of dimensional analysis?", back: "1) Check dimensional correctness of equations. 2) Convert units from one system to another. 3) Derive relationships between physical quantities.", difficulty: "medium", examImportance: "high", tags: ["uses", "dimensional analysis"] },
  { id: "phy11-p2-dim-017", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Dimensional Analysis", type: "concept", front: "What are the limitations of dimensional analysis?", back: "1) Cannot determine dimensionless constants. 2) Cannot derive equations with more than one quantity on one side. 3) Cannot distinguish between quantities with same dimensions (e.g., work and torque).", difficulty: "hard", examImportance: "medium", tags: ["limitations", "dimensional analysis"] },
  { id: "phy11-p2-sigfig-018", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Significant Figures", type: "definition", front: "What are significant figures?", back: "The meaningful digits in a measured value, including all certain digits and the first uncertain digit.", difficulty: "easy", examImportance: "high", tags: ["significant figures", "precision"] },
  { id: "phy11-p2-sigfig-019", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Significant Figures", type: "concept", front: "How many significant figures are in 0.00400?", back: "Three (4, 0, 0). Leading zeros are not significant; trailing zeros after decimal are significant.", difficulty: "medium", examImportance: "high", tags: ["significant figures", "counting"] },
  { id: "phy11-p2-sigfig-020", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Significant Figures", type: "concept", front: "How many significant figures are in 2.300 × 10⁴?", back: "Four (2, 3, 0, 0). All digits in the coefficient are significant.", difficulty: "medium", examImportance: "medium", tags: ["significant figures", "scientific notation"] },
  { id: "phy11-p2-sigfig-021", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Significant Figures", type: "concept", front: "In multiplication/division, how is the result rounded?", back: "The result should have the same number of significant figures as the quantity with the fewest significant figures.", difficulty: "medium", examImportance: "high", tags: ["significant figures", "rules", "multiplication"] },
  { id: "phy11-p2-sigfig-022", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Significant Figures", type: "concept", front: "In addition/subtraction, how is the result rounded?", back: "The result should have the same number of decimal places as the quantity with the fewest decimal places.", difficulty: "medium", examImportance: "high", tags: ["significant figures", "rules", "addition"] },
  { id: "phy11-p2-sigfig-023", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Significant Figures", type: "mistake", front: "Common mistake with significant figures in multiplication?", back: "Keeping more significant figures in the answer than in the least precise input. Example: 2.5 × 3.42 = 8.6 (not 8.55).", difficulty: "medium", examImportance: "high", tags: ["mistake", "significant figures"] },
  { id: "phy11-p2-acc-024", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Accuracy and Precision", type: "difference", front: "Difference between accuracy and precision?", back: "Accuracy = closeness to true value. Precision = closeness of repeated measurements to each other.", difficulty: "medium", examImportance: "high", tags: ["accuracy", "precision", "difference"] },
  { id: "phy11-p2-acc-025", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Accuracy and Precision", type: "mistake", front: "Common mistake about accuracy and precision?", back: "Treating them as the same. A precise instrument may not be accurate (systematic error), and an accurate instrument may not be precise (random scatter).", difficulty: "medium", examImportance: "high", tags: ["mistake", "accuracy", "precision"] },
  { id: "phy11-p2-err-026", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Errors", type: "definition", front: "What is absolute error?", back: "The magnitude of the difference between an individual measured value and the mean value: Δa = |a_i - ā|.", difficulty: "medium", examImportance: "high", tags: ["error", "absolute error"] },
  { id: "phy11-p2-err-027", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Errors", type: "formula", front: "Formula for mean absolute error?", back: "Δā = (Σ|Δa_i|) / n, where Δa_i are individual absolute errors and n is the number of observations.", difficulty: "medium", examImportance: "high", tags: ["error", "mean absolute error", "formula"] },
  { id: "phy11-p2-err-028", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Errors", type: "formula", front: "Formula for relative error?", back: "Relative error = Δa / ā (mean absolute error divided by mean value).", difficulty: "medium", examImportance: "high", tags: ["error", "relative error", "formula"] },
  { id: "phy11-p2-err-029", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Errors", type: "formula", front: "Formula for percentage error?", back: "Percentage error = (Δa / ā) × 100", difficulty: "easy", examImportance: "high", tags: ["error", "percentage error", "formula"] },
  { id: "phy11-p2-err-030", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Errors", type: "concept", front: "How do errors combine in addition/subtraction?", back: "Absolute errors add: Δz = Δa + Δb (for z = a + b or z = a - b).", difficulty: "medium", examImportance: "high", tags: ["error", "propagation", "addition"] },
  { id: "phy11-p2-err-031", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Errors", type: "concept", front: "How do errors combine in multiplication/division?", back: "Relative errors add: Δz/z = Δa/a + Δb/b (for z = a×b or z = a/b).", difficulty: "hard", examImportance: "high", tags: ["error", "propagation", "multiplication"] },
  { id: "phy11-p2-err-032", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Errors", type: "concept", front: "How does error propagate for z = aⁿ?", back: "Δz/z = n(Δa/a). The relative error is multiplied by the power.", difficulty: "hard", examImportance: "high", tags: ["error", "propagation", "power"] },
  { id: "phy11-p2-err-033", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Errors", type: "numerical", front: "A length is measured as 5.0 ± 0.1 cm. What is the percentage error?", back: "(0.1 / 5.0) × 100 = 2%", difficulty: "medium", examImportance: "high", tags: ["error", "percentage", "numerical"] },
  { id: "phy11-p2-err-034", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Errors", type: "numerical", front: "If x = a×b where a = 2.0 ± 0.1 and b = 3.0 ± 0.2, what is the relative error in x?", back: "Δx/x = 0.1/2.0 + 0.2/3.0 = 0.05 + 0.067 = 0.117 (or 11.7%)", difficulty: "hard", examImportance: "medium", tags: ["error", "propagation", "numerical"] },
  { id: "phy11-p2-vc-035", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Vernier Calipers", type: "definition", front: "What is the least count of a vernier calipers?", back: "The smallest measurement it can make: LC = (1 MSD - 1 VSD), where MSD = main scale division, VSD = vernier scale division.", difficulty: "medium", examImportance: "high", tags: ["vernier", "least count"] },
  { id: "phy11-p2-vc-036", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Vernier Calipers", type: "formula", front: "How do you calculate the reading of a vernier calipers?", back: "Reading = MSR + (VSR × LC), where MSR = main scale reading, VSR = vernier scale coincidence, LC = least count.", difficulty: "medium", examImportance: "high", tags: ["vernier", "reading", "formula"] },
  { id: "phy11-p2-vc-037", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Vernier Calipers", type: "concept", front: "What is zero error in a vernier calipers?", back: "If the zero of the vernier scale does not coincide with the zero of the main scale when jaws are closed. Positive zero error is added; negative is subtracted.", difficulty: "hard", examImportance: "high", tags: ["vernier", "zero error"] },
  { id: "phy11-p2-vc-038", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Vernier Calipers", type: "mistake", front: "Common mistake when using vernier calipers?", back: "Forgetting to apply zero correction. If zero error is positive, it must be subtracted from the reading; if negative, added.", difficulty: "medium", examImportance: "high", tags: ["mistake", "vernier", "zero error"] },
  { id: "phy11-p2-sg-039", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Screw Gauge", type: "definition", front: "What is the pitch of a screw gauge?", back: "The distance moved by the screw per rotation of the circular scale.", difficulty: "medium", examImportance: "high", tags: ["screw gauge", "pitch"] },
  { id: "phy11-p2-sg-040", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Screw Gauge", type: "formula", front: "Formula for least count of a screw gauge?", back: "LC = Pitch / Number of divisions on circular scale.", difficulty: "medium", examImportance: "high", tags: ["screw gauge", "least count", "formula"] },
  { id: "phy11-p2-sg-041", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Screw Gauge", type: "formula", front: "How do you calculate the reading of a screw gauge?", back: "Reading = PSR + (CSR × LC), where PSR = pitch scale reading, CSR = circular scale reading, LC = least count.", difficulty: "medium", examImportance: "high", tags: ["screw gauge", "reading", "formula"] },
  { id: "phy11-p2-sg-042", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Screw Gauge", type: "mistake", front: "Common mistake with screw gauge zero error?", back: "Not checking zero error before measurement. If zero of circular scale is below the reference line, zero error is positive and must be subtracted.", difficulty: "medium", examImportance: "high", tags: ["mistake", "screw gauge", "zero error"] },
  { id: "phy11-p2-conv-043", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Unit Conversion", type: "formula", front: "1 parsec = ? meters", back: "3.086 × 10¹⁶ m", difficulty: "hard", examImportance: "medium", tags: ["conversion", "parsec", "astronomy"] },
  { id: "phy11-p2-conv-044", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Unit Conversion", type: "formula", front: "1 light year = ? meters", back: "9.46 × 10¹⁵ m", difficulty: "medium", examImportance: "medium", tags: ["conversion", "light year"] },
  { id: "phy11-p2-conv-045", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Unit Conversion", type: "formula", front: "1 Angstrom (Å) = ? meters", back: "10⁻¹⁰ m", difficulty: "easy", examImportance: "medium", tags: ["conversion", "angstrom"] },
  { id: "phy11-p2-conv-046", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Unit Conversion", type: "numerical", front: "Convert 72 km/h to m/s.", back: "72 × (1000/3600) = 72 × (5/18) = 20 m/s", difficulty: "easy", examImportance: "high", tags: ["conversion", "numerical", "speed"] },
  { id: "phy11-p2-conv-047", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Unit Conversion", type: "numerical", front: "Convert 1 m/s to km/h.", back: "1 × (3600/1000) = 3.6 km/h", difficulty: "easy", examImportance: "high", tags: ["conversion", "numerical"] },
  { id: "phy11-p2-dim-048", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Dimensional Analysis", type: "application", front: "Check if v = u + at is dimensionally correct.", back: "Yes. [v] = [LT⁻¹], [u] = [LT⁻¹], [at] = [LT⁻²][T] = [LT⁻¹]. All terms have the same dimensions.", difficulty: "medium", examImportance: "high", tags: ["dimensional check", "kinematics"] },
  { id: "phy11-p2-dim-049", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Dimensional Analysis", type: "application", front: "Check if s = ut + ½at² is dimensionally correct.", back: "Yes. [s] = [L], [ut] = [LT⁻¹][T] = [L], [at²] = [LT⁻²][T²] = [L]. All terms = [L].", difficulty: "medium", examImportance: "high", tags: ["dimensional check", "kinematics"] },
  { id: "phy11-p2-dim-050", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Dimensional Analysis", type: "mistake", front: "What is a common mistake when checking dimensional correctness?", back: "Treating dimensions as units. Dimensions use M, L, T — not kg, m, s. Also, dimensionless constants like ½ cannot be verified.", difficulty: "medium", examImportance: "medium", tags: ["mistake", "dimensions", "units"] },
  { id: "phy11-p2-misc-051", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Miscellaneous", type: "definition", front: "What is the least count of an instrument?", back: "The smallest measurement that can be taken accurately with that instrument.", difficulty: "easy", examImportance: "high", tags: ["least count", "definition"] },
  { id: "phy11-p2-misc-052", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Miscellaneous", type: "concept", front: "Why do we use significant figures?", back: "To indicate the precision of a measurement. They show which digits are reliable and which are uncertain.", difficulty: "easy", examImportance: "medium", tags: ["significant figures", "purpose"] },
  { id: "phy11-p2-misc-053", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Miscellaneous", type: "exam-tip", front: "Exam tip: How to approach error calculation problems?", back: "1) Identify the formula. 2) Determine if it's addition (absolute errors add) or multiplication (relative errors add). 3) Calculate each error. 4) Combine and express as ± value or percentage.", difficulty: "medium", examImportance: "high", tags: ["exam tip", "error", "strategy"] },
  { id: "phy11-p2-misc-054", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Miscellaneous", type: "jee", front: "JEE: If the percentage errors in measuring a, b, c are 1%, 2%, 3% and x = a²b³c⁻¹, find the percentage error in x.", back: "Δx/x = 2(1%) + 3(2%) + 1(3%) = 2% + 6% + 3% = 11%", difficulty: "hard", examImportance: "high", tags: ["JEE", "error", "propagation"] },
  { id: "phy11-p2-misc-055", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Miscellaneous", type: "unit", front: "What is 1 fermi (femtometre)?", back: "10⁻¹⁵ m — used to measure nuclear distances (e.g., radius of a nucleus).", difficulty: "medium", examImportance: "low", tags: ["units", "fermi", "nuclear"] },
  { id: "phy11-p2-misc-056", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Miscellaneous", type: "concept", front: "What is the relation between radian and degree?", back: "π radians = 180°, so 1 radian = 180°/π ≈ 57.3°", difficulty: "medium", examImportance: "medium", tags: ["radian", "degree", "conversion"] },
  { id: "phy11-p2-misc-057", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Miscellaneous", type: "definition", front: "What is a coherent system of units?", back: "A system where derived units are obtained by multiplying/dividing base units without numerical factors. SI is a coherent system.", difficulty: "hard", examImportance: "low", tags: ["coherent", "system", "units"] },
  { id: "phy11-p2-misc-058", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Miscellaneous", type: "concept", front: "What is the difference between mass and weight?", back: "Mass is the amount of matter (scalar, SI unit kg, constant). Weight is the gravitational force on a body (vector, SI unit N, varies with g).", difficulty: "easy", examImportance: "high", tags: ["mass", "weight", "difference"] },
  { id: "phy11-p2-misc-059", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Miscellaneous", type: "mistake", front: "Common mistake: Confusing mass and weight units?", back: "Mass is measured in kg; weight is measured in Newton (N = kg·m/s²). Saying 'my weight is 60 kg' is technically incorrect in physics.", difficulty: "medium", examImportance: "medium", tags: ["mistake", "mass", "weight"] },
  { id: "phy11-p2-misc-060", subject: "physics", subjectName: "Physics", chapterId: "p2", chapter: "Units and Measurements", topic: "Miscellaneous", type: "exam-tip", front: "Exam tip: What to remember about significant figures in the final answer?", back: "Always round the final answer to the correct number of significant figures based on the least precise input. Do not round intermediate steps.", difficulty: "medium", examImportance: "high", tags: ["exam tip", "significant figures", "rounding"] },

  // ===== MOTION IN A STRAIGHT LINE (p3) — 60 cards =====
  { id: "phy11-p3-rest-001", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Rest and Motion", type: "definition", front: "When is a body said to be at rest?", back: "When its position does not change with time relative to a given reference point.", difficulty: "easy", examImportance: "medium", tags: ["rest", "motion", "basics"] },
  { id: "phy11-p3-rest-002", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Rest and Motion", type: "concept", front: "Is rest and motion absolute or relative?", back: "Relative. A body at rest relative to one observer may be in motion relative to another. There is no absolute rest.", difficulty: "medium", examImportance: "high", tags: ["relative", "rest", "motion"] },
  { id: "phy11-p3-pos-003", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Position and Displacement", type: "definition", front: "What is displacement?", back: "The change in position of a body in a definite direction. It is a vector quantity (SI unit: metre).", difficulty: "easy", examImportance: "high", tags: ["displacement", "vector"] },
  { id: "phy11-p3-pos-004", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Position and Displacement", type: "definition", front: "What is distance?", back: "The total path length travelled by a body. It is a scalar quantity (SI unit: metre).", difficulty: "easy", examImportance: "high", tags: ["distance", "scalar"] },
  { id: "phy11-p3-pos-005", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Position and Displacement", type: "difference", front: "Difference between distance and displacement?", back: "Distance is the total path length (scalar, always positive). Displacement is the shortest straight-line distance from initial to final position (vector, can be zero or negative).", difficulty: "easy", examImportance: "high", tags: ["distance", "displacement", "difference"] },
  { id: "phy11-p3-pos-006", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Position and Displacement", type: "concept", front: "Can displacement be zero when distance is not zero?", back: "Yes. If an object returns to its starting point, displacement is zero but distance is the total path travelled.", difficulty: "medium", examImportance: "high", tags: ["displacement", "distance", "concept"] },
  { id: "phy11-p3-pos-007", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Position and Displacement", type: "numerical", front: "A body moves 3 m east then 4 m north. What is the distance and displacement?", back: "Distance = 3 + 4 = 7 m. Displacement = √(3² + 4²) = 5 m (north-east direction).", difficulty: "medium", examImportance: "high", tags: ["numerical", "distance", "displacement"] },
  { id: "phy11-p3-speed-008", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Speed", type: "definition", front: "What is speed?", back: "The rate of change of distance with time. It is a scalar quantity (SI unit: m/s).", difficulty: "easy", examImportance: "high", tags: ["speed", "scalar"] },
  { id: "phy11-p3-speed-009", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Speed", type: "formula", front: "Formula for average speed?", back: "Average speed = Total distance / Total time", difficulty: "easy", examImportance: "high", tags: ["average speed", "formula"] },
  { id: "phy11-p3-speed-010", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Speed", type: "definition", front: "What is instantaneous speed?", back: "The speed of a body at a particular instant: v = dx/dt (the magnitude of instantaneous velocity).", difficulty: "medium", examImportance: "high", tags: ["instantaneous speed", "derivative"] },
  { id: "phy11-p3-speed-011", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Speed", type: "numerical", front: "A car travels 100 km in 2 hours. What is the average speed?", back: "Average speed = 100/2 = 50 km/h", difficulty: "easy", examImportance: "high", tags: ["numerical", "average speed"] },
  { id: "phy11-p3-speed-012", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Speed", type: "numerical", front: "A body travels half the distance at 40 km/h and the other half at 60 km/h. Find the average speed.", back: "Average speed = 2v₁v₂/(v₁+v₂) = 2(40)(60)/(40+60) = 4800/100 = 48 km/h", difficulty: "hard", examImportance: "high", tags: ["numerical", "harmonic mean", "average speed"] },
  { id: "phy11-p3-vel-013", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Velocity", type: "definition", front: "What is velocity?", back: "The rate of change of displacement with time. It is a vector quantity (SI unit: m/s).", difficulty: "easy", examImportance: "high", tags: ["velocity", "vector"] },
  { id: "phy11-p3-vel-014", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Velocity", type: "formula", front: "Formula for average velocity?", back: "Average velocity = Total displacement / Total time", difficulty: "easy", examImportance: "high", tags: ["average velocity", "formula"] },
  { id: "phy11-p3-vel-015", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Velocity", type: "definition", front: "What is instantaneous velocity?", back: "The velocity at a particular instant: v = dx/dt. It is the slope of the position-time graph at that point.", difficulty: "medium", examImportance: "high", tags: ["instantaneous velocity", "derivative"] },
  { id: "phy11-p3-vel-016", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Velocity", type: "difference", front: "Difference between speed and velocity?", back: "Speed is scalar (magnitude only, always positive). Velocity is vector (magnitude + direction, can be negative). Speed = |velocity|.", difficulty: "easy", examImportance: "high", tags: ["speed", "velocity", "difference"] },
  { id: "phy11-p3-vel-017", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Velocity", type: "mistake", front: "Common mistake in average velocity calculations?", back: "Using total distance instead of displacement. Average velocity = displacement/time, not distance/time.", difficulty: "medium", examImportance: "high", tags: ["mistake", "average velocity"] },
  { id: "phy11-p3-vel-018", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Velocity", type: "numerical", front: "A body moves from A to B (100 m) in 10 s, then B to A (100 m) in 10 s. Find average velocity and average speed.", back: "Average velocity = 0 (displacement = 0). Average speed = 200/20 = 10 m/s.", difficulty: "medium", examImportance: "high", tags: ["numerical", "average velocity", "average speed"] },
  { id: "phy11-p3-acc-019", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Acceleration", type: "definition", front: "What is acceleration?", back: "The rate of change of velocity with time. It is a vector quantity (SI unit: m/s²).", difficulty: "easy", examImportance: "high", tags: ["acceleration", "vector"] },
  { id: "phy11-p3-acc-020", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Acceleration", type: "formula", front: "Formula for average acceleration?", back: "a = (v - u) / t, where v = final velocity, u = initial velocity, t = time.", difficulty: "easy", examImportance: "high", tags: ["acceleration", "formula"] },
  { id: "phy11-p3-acc-021", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Acceleration", type: "definition", front: "What is instantaneous acceleration?", back: "a = dv/dt = d²x/dt². It is the slope of the velocity-time graph at that point.", difficulty: "medium", examImportance: "high", tags: ["instantaneous acceleration", "derivative"] },
  { id: "phy11-p3-acc-022", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Acceleration", type: "concept", front: "Can a body have zero velocity and non-zero acceleration?", back: "Yes. At the highest point of a ball thrown upward, velocity is zero but acceleration = g (downward).", difficulty: "medium", examImportance: "high", tags: ["acceleration", "velocity", "concept"] },
  { id: "phy11-p3-acc-023", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Acceleration", type: "concept", front: "Can a body have constant speed but non-zero acceleration?", back: "Yes. In uniform circular motion, speed is constant but direction changes, so velocity changes, giving centripetal acceleration.", difficulty: "hard", examImportance: "high", tags: ["acceleration", "speed", "circular motion"] },
  { id: "phy11-p3-acc-024", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Acceleration", type: "concept", front: "What is retardation/deceleration?", back: "Negative acceleration — when velocity decreases with time. The acceleration vector is opposite to the velocity vector.", difficulty: "easy", examImportance: "high", tags: ["retardation", "deceleration"] },
  { id: "phy11-p3-kin-025", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Equations of Motion", type: "formula", front: "State the first equation of motion.", back: "v = u + at (relates final velocity, initial velocity, acceleration, and time).", difficulty: "easy", examImportance: "high", tags: ["kinematics", "equation", "formula"] },
  { id: "phy11-p3-kin-026", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Equations of Motion", type: "formula", front: "State the second equation of motion.", back: "s = ut + ½at² (relates displacement, initial velocity, acceleration, and time).", difficulty: "easy", examImportance: "high", tags: ["kinematics", "equation", "formula"] },
  { id: "phy11-p3-kin-027", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Equations of Motion", type: "formula", front: "State the third equation of motion.", back: "v² = u² + 2as (relates final velocity, initial velocity, acceleration, and displacement — no time).", difficulty: "easy", examImportance: "high", tags: ["kinematics", "equation", "formula"] },
  { id: "phy11-p3-kin-028", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Equations of Motion", type: "formula", front: "What is the formula for distance in the nth second?", back: "s_n = u + (a/2)(2n - 1), where n is the second number.", difficulty: "medium", examImportance: "high", tags: ["kinematics", "nth second"] },
  { id: "phy11-p3-kin-029", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Equations of Motion", type: "numerical", front: "A car starts from rest and accelerates at 4 m/s² for 5 s. Find the final velocity and distance.", back: "v = 0 + 4(5) = 20 m/s. s = 0 + ½(4)(25) = 50 m.", difficulty: "easy", examImportance: "high", tags: ["numerical", "kinematics"] },
  { id: "phy11-p3-kin-030", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Equations of Motion", type: "numerical", front: "A body starts from rest and attains 20 m/s in 5 s. Find acceleration and distance.", back: "a = (20-0)/5 = 4 m/s². s = 0(5) + ½(4)(25) = 50 m.", difficulty: "easy", examImportance: "high", tags: ["numerical", "kinematics"] },
  { id: "phy11-p3-kin-031", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Equations of Motion", type: "numerical", front: "A ball is dropped from 80 m. Find the time to reach the ground (g = 10 m/s²).", back: "s = ½gt² → 80 = ½(10)t² → t² = 16 → t = 4 s.", difficulty: "medium", examImportance: "high", tags: ["numerical", "free fall"] },
  { id: "phy11-p3-kin-032", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Equations of Motion", type: "numerical", front: "A car accelerates from 10 m/s to 30 m/s in 4 s. Find acceleration and distance.", back: "a = (30-10)/4 = 5 m/s². s = (10)(4) + ½(5)(16) = 40 + 40 = 80 m.", difficulty: "medium", examImportance: "high", tags: ["numerical", "kinematics"] },
  { id: "phy11-p3-kin-033", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Equations of Motion", type: "mistake", front: "Common mistake when using equations of motion?", back: "Using the wrong sign for acceleration. If a body decelerates, 'a' must be negative. Also forgetting that these equations apply only for uniform acceleration.", difficulty: "medium", examImportance: "high", tags: ["mistake", "kinematics", "sign convention"] },
  { id: "phy11-p3-graph-034", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Graphs", type: "concept", front: "What does the slope of a position-time graph represent?", back: "Velocity. A steeper slope means higher velocity. A horizontal line means the body is at rest.", difficulty: "easy", examImportance: "high", tags: ["graph", "position-time", "slope"] },
  { id: "phy11-p3-graph-035", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Graphs", type: "concept", front: "What does the slope of a velocity-time graph represent?", back: "Acceleration. A steeper slope means higher acceleration. A horizontal line means constant velocity (zero acceleration).", difficulty: "easy", examImportance: "high", tags: ["graph", "velocity-time", "slope"] },
  { id: "phy11-p3-graph-036", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Graphs", type: "concept", front: "What does the area under a velocity-time graph represent?", back: "Displacement. The area between the graph and the time axis gives the displacement in that time interval.", difficulty: "easy", examImportance: "high", tags: ["graph", "velocity-time", "area"] },
  { id: "phy11-p3-graph-037", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Graphs", type: "concept", front: "What does the area under an acceleration-time graph represent?", back: "Change in velocity (Δv) over that time interval.", difficulty: "medium", examImportance: "medium", tags: ["graph", "acceleration-time", "area"] },
  { id: "phy11-p3-graph-038", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Graphs", type: "mistake", front: "Common mistake with motion graphs?", back: "Confusing slope and area. Slope of v-t graph = acceleration; area under v-t graph = displacement. Remember: slope = rate of change, area = accumulation.", difficulty: "medium", examImportance: "high", tags: ["mistake", "graph", "slope", "area"] },
  { id: "phy11-p3-graph-039", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Graphs", type: "concept", front: "What does a position-time graph look like for uniform motion?", back: "A straight line passing through (or from) the origin with a constant slope. The slope equals the constant velocity.", difficulty: "easy", examImportance: "high", tags: ["graph", "uniform motion"] },
  { id: "phy11-p3-graph-040", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Graphs", type: "concept", front: "What does a position-time graph look like for uniformly accelerated motion?", back: "A parabola. The curvature increases with acceleration. The slope at any point gives the instantaneous velocity.", difficulty: "medium", examImportance: "high", tags: ["graph", "accelerated motion", "parabola"] },
  { id: "phy11-p3-graph-041", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Graphs", type: "concept", front: "What does the velocity-time graph for free fall look like?", back: "A straight line with negative slope (if upward is positive) starting from initial velocity and decreasing. Slope = -g.", difficulty: "medium", examImportance: "high", tags: ["graph", "free fall"] },
  { id: "phy11-p3-free-042", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Free Fall", type: "definition", front: "What is free fall?", back: "Motion of a body under the influence of gravity alone (no air resistance). Acceleration = g ≈ 9.8 m/s² downward.", difficulty: "easy", examImportance: "high", tags: ["free fall", "gravity"] },
  { id: "phy11-p3-free-043", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Free Fall", type: "concept", front: "For a body thrown upward, what is the velocity and acceleration at the highest point?", back: "Velocity = 0 (momentarily). Acceleration = g (downward, constant throughout the motion).", difficulty: "medium", examImportance: "high", tags: ["free fall", "highest point"] },
  { id: "phy11-p3-free-044", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Free Fall", type: "formula", front: "For a body thrown upward with velocity u, what is the maximum height?", back: "H = u² / (2g) (using v² = u² + 2as with v = 0, a = -g).", difficulty: "medium", examImportance: "high", tags: ["free fall", "max height", "formula"] },
  { id: "phy11-p3-free-045", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Free Fall", type: "formula", front: "Time to reach maximum height for a body thrown upward with velocity u?", back: "t = u / g (using v = u - gt with v = 0 at the top).", difficulty: "medium", examImportance: "high", tags: ["free fall", "time", "formula"] },
  { id: "phy11-p3-free-046", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Free Fall", type: "concept", front: "For a body thrown upward, what is the time of ascent compared to time of descent?", back: "Equal (if air resistance is neglected). Time up = Time down = u/g. Total time = 2u/g.", difficulty: "medium", examImportance: "high", tags: ["free fall", "ascent", "descent"] },
  { id: "phy11-p3-sign-047", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Sign Convention", type: "concept", front: "What is the sign convention for motion in a straight line?", back: "Choose a positive direction (usually right or up). Velocities, displacements, and accelerations in that direction are positive; opposite are negative.", difficulty: "medium", examImportance: "high", tags: ["sign convention", "basics"] },
  { id: "phy11-p3-sign-048", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Sign Convention", type: "mistake", front: "Common mistake with sign convention?", back: "Not being consistent. If upward is positive, then g = -9.8 m/s². Mixing signs leads to wrong answers. Always state your convention first.", difficulty: "medium", examImportance: "high", tags: ["mistake", "sign convention"] },
  { id: "phy11-p3-rel-049", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Relative Velocity", type: "definition", front: "What is relative velocity?", back: "The velocity of a body as observed from another (possibly moving) frame. v_AB = v_A - v_B (velocity of A relative to B).", difficulty: "medium", examImportance: "high", tags: ["relative velocity", "definition"] },
  { id: "phy11-p3-rel-050", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Relative Velocity", type: "numerical", front: "Two cars move in the same direction at 60 km/h and 40 km/h. What is the velocity of the first relative to the second?", back: "v_12 = v_1 - v_2 = 60 - 40 = 20 km/h (same direction).", difficulty: "medium", examImportance: "high", tags: ["relative velocity", "numerical"] },
  { id: "phy11-p3-rel-051", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Relative Velocity", type: "numerical", front: "Two trains move towards each other at 50 km/h and 60 km/h. What is their relative velocity?", back: "v_rel = 50 + 60 = 110 km/h (opposite directions → add magnitudes).", difficulty: "medium", examImportance: "high", tags: ["relative velocity", "numerical"] },
  { id: "phy11-p3-uni-052", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Uniform Motion", type: "definition", front: "What is uniform motion?", back: "Motion with constant velocity (constant speed in a straight line). Acceleration = 0.", difficulty: "easy", examImportance: "medium", tags: ["uniform motion", "definition"] },
  { id: "phy11-p3-uni-053", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Uniform Motion", type: "definition", front: "What is uniformly accelerated motion?", back: "Motion with constant acceleration. Velocity changes at a constant rate. The three equations of motion apply.", difficulty: "easy", examImportance: "high", tags: ["uniform acceleration", "definition"] },
  { id: "phy11-p3-deri-054", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Derivations", type: "application", front: "How do you derive v = u + at graphically?", back: "On a v-t graph for uniform acceleration: slope = (v - u)/t = a. Therefore v = u + at.", difficulty: "medium", examImportance: "high", tags: ["derivation", "graphical", "v=u+at"] },
  { id: "phy11-p3-deri-055", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Derivations", type: "application", front: "How do you derive s = ut + ½at² graphically?", back: "Area under v-t graph = rectangle (u × t) + triangle (½ × (v-u) × t) = ut + ½(at)t = ut + ½at².", difficulty: "hard", examImportance: "high", tags: ["derivation", "graphical", "area"] },
  { id: "phy11-p3-misc-056", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Miscellaneous", type: "exam-tip", front: "Exam tip: How to choose which equation of motion to use?", back: "If time is given/asked → use v = u + at or s = ut + ½at². If time is NOT involved → use v² = u² + 2as. If asking for distance in nth second → use s_n = u + (a/2)(2n-1).", difficulty: "medium", examImportance: "high", tags: ["exam tip", "strategy", "equations"] },
  { id: "phy11-p3-misc-057", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Miscellaneous", type: "mistake", front: "Common mistake: Forgetting units in the answer?", back: "Always include the correct SI unit: m/s for velocity, m/s² for acceleration, m for displacement. An answer without units is incomplete.", difficulty: "easy", examImportance: "high", tags: ["mistake", "units"] },
  { id: "phy11-p3-misc-058", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Miscellaneous", type: "jee", front: "JEE: A particle moves with v = 3t² + 2t. Find the acceleration at t = 2 s.", back: "a = dv/dt = 6t + 2. At t = 2: a = 6(2) + 2 = 14 m/s².", difficulty: "hard", examImportance: "high", tags: ["JEE", "calculus", "acceleration"] },
  { id: "phy11-p3-misc-059", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Miscellaneous", type: "jee", front: "JEE: A body is thrown up with u = 20 m/s. Find the distance travelled in 3 s (g = 10).", back: "Time to top = u/g = 2 s. Height = u²/2g = 20 m. Then falls for 1 s: distance = ½g(1)² = 5 m. Total distance = 20 + 5 = 25 m.", difficulty: "hard", examImportance: "high", tags: ["JEE", "free fall", "distance"] },
  { id: "phy11-p3-misc-060", subject: "physics", subjectName: "Physics", chapterId: "p3", chapter: "Motion in a Straight Line", topic: "Miscellaneous", type: "concept", front: "If a body moves with constant velocity, what is its acceleration?", back: "Zero. Constant velocity means no change in velocity, so a = 0. The v-t graph is a horizontal line.", difficulty: "easy", examImportance: "high", tags: ["constant velocity", "acceleration"] },
];

export default PHYSICS_FLASHCARDS;
